-- GENERATED by scripts/pg-schema.mjs from the live SQLite database.
-- Do not edit by hand: re-run the generator instead, and put judgement
-- calls in its OVERRIDE map so they survive the next run.
--
-- Row-level security is at the bottom. Every connection must set the
-- tenant before it reads anything:
--
--     SET LOCAL app.organization_id = '<org id>';
--
-- Without it the query returns no rows: on a fresh connection
-- current_setting() raises undefined_object, and once the parameter has
-- been set anywhere in the session it reads back empty, which matches
-- nothing. Either way a forgotten scope is an error or an empty result,
-- never a full-table read. That is the whole point.
--
-- The application must connect as a role that is NOT the table owner.
-- FORCE ROW LEVEL SECURITY below covers the owner too, but relying on it
-- alone means one table missing FORCE is a silent full-table read.
--

CREATE EXTENSION IF NOT EXISTS pgcrypto;  -- gen_random_bytes for id defaults

CREATE TABLE "accruals" (
