  "name" TEXT NOT NULL,
  "code" TEXT NOT NULL,
  "floor" BIGINT,
  "zone" TEXT,
  "beds" BIGINT DEFAULT 2 NOT NULL,
  "room_status" TEXT DEFAULT 'available' NOT NULL,
  "cleaning_status" TEXT DEFAULT 'clean' NOT NULL,
