-- ── Row-level security ──────────────────────────────────────────────────
--
-- The application connects as a role that is NOT the table owner and NOT
-- superuser, so these policies actually apply. FORCE makes them apply to
-- the owner too, which is what catches a migration script reading across
-- tenants by accident.

ALTER TABLE "accruals" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "accruals" FORCE ROW LEVEL SECURITY;
CREATE POLICY "accruals_tenant" ON "accruals"
  USING ("organization_id" = current_setting('app.organization_id'))
  WITH CHECK ("organization_id" = current_setting('app.organization_id'));

ALTER TABLE "additional_services" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "additional_services" FORCE ROW LEVEL SECURITY;
CREATE POLICY "additional_services_tenant" ON "additional_services"
  USING ("property_id" IN (SELECT "id" FROM "properties" WHERE "organization_id" = current_setting('app.organization_id')))
  WITH CHECK ("property_id" IN (SELECT "id" FROM "properties" WHERE "organization_id" = current_setting('app.organization_id')));

ALTER TABLE "ai_usage" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "ai_usage" FORCE ROW LEVEL SECURITY;
CREATE POLICY "ai_usage_tenant" ON "ai_usage"
  USING ("organization_id" = current_setting('app.organization_id'))
  WITH CHECK ("organization_id" = current_setting('app.organization_id'));

ALTER TABLE "amenities" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "amenities" FORCE ROW LEVEL SECURITY;
CREATE POLICY "amenities_tenant" ON "amenities"
  USING ("organization_id" = current_setting('app.organization_id'))
  WITH CHECK ("organization_id" = current_setting('app.organization_id'));

ALTER TABLE "amenity_categories" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "amenity_categories" FORCE ROW LEVEL SECURITY;
CREATE POLICY "amenity_categories_tenant" ON "amenity_categories"
  USING ("organization_id" = current_setting('app.organization_id'))
  WITH CHECK ("organization_id" = current_setting('app.organization_id'));

ALTER TABLE "app_connections" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "app_connections" FORCE ROW LEVEL SECURITY;
CREATE POLICY "app_connections_tenant" ON "app_connections"
  USING ("organization_id" = current_setting('app.organization_id'))
  WITH CHECK ("organization_id" = current_setting('app.organization_id'));

ALTER TABLE "app_users" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "app_users" FORCE ROW LEVEL SECURITY;
CREATE POLICY "app_users_tenant" ON "app_users"
  USING ("organization_id" = current_setting('app.organization_id') OR current_setting('app.organization_id') = '')
  WITH CHECK ("organization_id" = current_setting('app.organization_id'));

ALTER TABLE "app_wishes" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "app_wishes" FORCE ROW LEVEL SECURITY;
CREATE POLICY "app_wishes_tenant" ON "app_wishes"
  USING ("organization_id" = current_setting('app.organization_id'))
  WITH CHECK ("organization_id" = current_setting('app.organization_id'));

ALTER TABLE "availability_blocks" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "availability_blocks" FORCE ROW LEVEL SECURITY;
CREATE POLICY "availability_blocks_tenant" ON "availability_blocks"
  USING ("organization_id" = current_setting('app.organization_id'))
  WITH CHECK ("organization_id" = current_setting('app.organization_id'));

ALTER TABLE "booking_activity_log" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "booking_activity_log" FORCE ROW LEVEL SECURITY;
CREATE POLICY "booking_activity_log_tenant" ON "booking_activity_log"
  USING ("organization_id" = current_setting('app.organization_id'))
  WITH CHECK ("organization_id" = current_setting('app.organization_id'));

ALTER TABLE "booking_drafts" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "booking_drafts" FORCE ROW LEVEL SECURITY;
CREATE POLICY "booking_drafts_tenant" ON "booking_drafts"
